USE world_heritage_db;

DROP TABLE IF EXISTS heritage_questions_grade2;

CREATE TABLE heritage_questions_grade2 (
    id INT AUTO_INCREMENT PRIMARY KEY,
    chapter VARCHAR(100) NOT NULL,
    heritage_name VARCHAR(150) NOT NULL,
    feature_1 TEXT NOT NULL,
    feature_2 TEXT NOT NULL,
    feature_3 TEXT NOT NULL,
    tag_country VARCHAR(100),
    tag_criterion VARCHAR(20),
    tag_type VARCHAR(50),
    tag_special VARCHAR(50),
    tag_others VARCHAR(100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

